import shutilimport cv2import numpy as npimport pyautoguiimport timeimport pyperclipfrom PIL import ImageGrabimport osfrom logging_config import logger# 设置pyautogui的延迟（模拟人点击）pyautogui.PAUSE = 0.05# 防故障保护（移动到屏幕角落可终止）pyautogui.FAILSAFE = Truedef clear_files_in_directory(target_dir, skip_files=None, max_retry=3, retry_interval=0.5):    """    清理指定目录下的所有文件和子文件夹（保留目录本身）    :param target_dir: 要清理的目录路径    :param skip_files: 要跳过的文件/文件夹列表（如 ["保留文件.txt"]），默认None    :param max_retry: 文件被占用时的重试次数    :param retry_interval: 重试间隔（秒）    """    # 1. 校验目录是否存在    if not os.path.exists(target_dir):        logger.warning(f"清理目录不存在，已自动创建：{target_dir}")        os.makedirs(target_dir, exist_ok=True)        return    # 2. 初始化跳过列表（避免None导致报错）    skip_files = skip_files or []    # 转换为小写，避免大小写敏感问题    skip_files_lower = [f.lower() for f in skip_files]    # 3. 遍历目录并删除文件/文件夹    for root, dirs, files in os.walk(target_dir, topdown=False):        # 先删除文件        for file_name in files:            # 跳过指定文件            if file_name.lower() in skip_files_lower:                logger.info(f"跳过清理文件：{os.path.join(root, file_name)}")                continue            file_path = os.path.join(root, file_name)            retry_count = 0            while retry_count < max_retry:                try:                    os.remove(file_path)                    logger.info(f"成功删除文件：{file_path}")                    break                except PermissionError:                    # 文件被占用，重试                    retry_count += 1                    logger.warning(f"文件被占用，重试({retry_count}/{max_retry})：{file_path}")                    time.sleep(retry_interval)                except Exception as e:                    logger.error(f"删除文件失败：{file_path}，错误：{str(e)}")                    break        # 再删除子文件夹        for dir_name in dirs:            # 跳过指定文件夹            if dir_name.lower() in skip_files_lower:                logger.info(f"跳过清理文件夹：{os.path.join(root, dir_name)}")                continue            dir_path = os.path.join(root, dir_name)            retry_count = 0            while retry_count < max_retry:                try:                    shutil.rmtree(dir_path)                    logger.info(f"成功删除文件夹：{dir_path}")                    break                except PermissionError:                    retry_count += 1                    logger.warning(f"文件夹被占用，重试({retry_count}/{max_retry})：{dir_path}")                    time.sleep(retry_interval)                except Exception as e:                    logger.error(f"删除文件夹失败：{dir_path}，错误：{str(e)}")                    break    logger.info(f"目录清理完成：{target_dir}")def find_image(template_name, img_dir="images", threshold=0.8):    """    在屏幕上查找指定模板图片的位置    :param template_name: 模板图片名称    :param img_dir: 模板目录    :param threshold: 匹配阈值    :return: 匹配到的坐标(x, y)，未找到返回None    """    # 拼接模板图片路径    template_path = os.path.join(img_dir, template_name)    if not os.path.exists(template_path):        raise FileNotFoundError(f"模板图片不存在：{template_path}")    # 获取屏幕截图    screen = pyautogui.screenshot()    screen_gray = cv2.cvtColor(np.array(screen), cv2.COLOR_RGB2GRAY)    # 读取模板图片并灰度化    template = cv2.imread(template_path, 0)    h, w = template.shape[:2]    # 模板匹配    result = cv2.matchTemplate(screen_gray, template, cv2.TM_CCOEFF_NORMED)    loc = np.where(result >= threshold)    # 获取匹配位置的中心坐标    if len(loc[0]) > 0:        x = int(loc[1][0] + w / 2)        y = int(loc[0][0] + h / 2)        return (x, y)    return Nonedef find_image_and_click(template_name, click_type="left", img_dir="images", threshold=0.8, max_retry=5,                         retry_interval=0.2, stabilize_delay=0.3, confirm_click=True):    """    查找图像并点击（支持左键/右键），增加稳定性优化    :param template_name: 模板图片名称    :param click_type: 点击类型 "left"（左键）/"right"（右键）    :param img_dir: 模板目录    :param threshold: 匹配阈值    :param max_retry: 最大重试次数    :param retry_interval: 重试间隔（秒）    :param stabilize_delay: 找到图像后到点击前的稳定延迟（秒）    :param confirm_click: 是否在点击后再次确认图像仍存在（进一步提高稳定性）    """    retry_count = 0    while retry_count < max_retry:        # 第一次查找图像        pos = find_image(template_name, img_dir, threshold)        if pos:            # 1. 增加稳定延迟，确保界面完全就绪            time.sleep(stabilize_delay)            # 2. 再次确认图像仍在原位置（防止界面变化）            if confirm_click:                pos_check = find_image(template_name, img_dir, threshold)                if not pos_check or abs(pos_check[0] - pos[0]) > 5 or abs(pos_check[1] - pos[1]) > 5:                    retry_count += 1                    time.sleep(retry_interval)                    continue            # 3. 移动鼠标到目标位置（先移动再点击，更稳定）            pyautogui.moveTo(pos[0], pos[1], duration=0.1)  # 0.1秒平滑移动            time.sleep(0.1)  # 移动后再短暂等待            # 4. 执行点击操作            if click_type == "left":                pyautogui.click(pos[0], pos[1])            elif click_type == "right":                pyautogui.rightClick(pos[0], pos[1])            else:                raise ValueError(f"不支持的点击类型：{click_type}，仅支持 left/right")            # 5. 点击后短暂等待，确保点击生效            time.sleep(0.1)            return        # 未找到则重试        retry_count += 1        time.sleep(retry_interval)    raise RuntimeError(f"重试{max_retry}次后仍未找到图像：{template_name}（目录：{img_dir}）")def find_image_and_click_with_offset(template_name, x_offset=0, y_offset=0, click_type="left", img_dir="images",                                     threshold=0.8, max_retry=5, retry_interval=0.2):    """    查找图像并偏移点击（解决目标区域不在图像中心的问题）    :param template_name: 模板图片名称    :param x_offset: X轴偏移量（正数右移，负数左移）    :param y_offset: Y轴偏移量（正数下移，负数上移）    :param click_type: 点击类型 "left"/"right"    :param img_dir: 模板目录    :param threshold: 匹配阈值    :param max_retry: 最大重试次数    :param retry_interval: 重试间隔    """    retry_count = 0    while retry_count < max_retry:        pos = find_image(template_name, img_dir, threshold)        if pos:            # 计算偏移后的坐标            target_x = pos[0] + x_offset            target_y = pos[1] + y_offset            # 执行点击            if click_type == "left":                pyautogui.click(target_x, target_y)            elif click_type == "right":                pyautogui.rightClick(target_x, target_y)            else:                raise ValueError(f"不支持的点击类型：{click_type}，仅支持 left/right")            return        retry_count += 1        time.sleep(retry_interval)    raise RuntimeError(        f"重试{max_retry}次后仍未找到图像：{template_name}（目录：{img_dir}），偏移量(x:{x_offset}, y:{y_offset})")def input_address_with_shortcut(address, shortcut="^l", interval=0.1):    """    用快捷键激活地址栏并输入路径    :param address: 要输入的路径    :param shortcut: 激活地址栏的快捷键（默认Ctrl+L）    :param interval: 输入间隔（秒）    """    # 激活地址栏    pyautogui.hotkey(*shortcut.split('+'))    time.sleep(interval)    # 清空原有内容    pyautogui.hotkey('ctrl', 'a')    pyautogui.press('backspace')    time.sleep(interval)    # 输入新地址    pyautogui.typewrite(address, interval=interval)    # 回车确认    pyautogui.press('enter')    time.sleep(interval)def escape_pywinauto_chars(text):    """    全面转义pywinauto的type_keys中所有特殊字符，确保输入完全一致    覆盖：括号、空格、加号、井号、百分号、方括号、中文括号等    """    # 定义需要转义的特殊字符映射表（键=原字符，值=转义后字符）    escape_map = {        '{': '{{}',  # 左大括号        '}': '{}}',  # 右大括号        '(': '{(}',  # 左小括号        ')': '{)}',  # 右小括号        '[': '{[}',  # 左方括号        ']': '{]}',  # 右方括号        '+': '{+}',  # 加号        '#': '{#}',  # 井号        '%': '{%}',  # 百分号（避免被识别为Alt快捷键）        '^': '{^}',  # 脱字符（避免被识别为Ctrl快捷键）        '~': '{~}',  # 波浪号        '!': '{!}',  # 感叹号        '@': '{@}',  # @符号        ' ': '{SPACE}',  # 空格（更可靠的方式）        '（': '{（}',  # 中文左括号        '）': '{）}',  # 中文右括号        '【': '{【}',  # 中文左方括号        '】': '{】}',  # 中文右方括号    }    # 逐个替换特殊字符    escaped_text = text    for char, escaped_char in escape_map.items():        escaped_text = escaped_text.replace(char, escaped_char)    return escaped_textdef safe_paste_filename(filename, edit_control):    """    无返回值！直接在输入框控件内粘贴文件名（核心：避免None赋值）    :param filename: 要输入的文件名（如 id50_SI-NPW-YMTC(5-4UM)）    :param edit_control: pywinauto的输入框控件对象    """    # 1. 复制文件名到剪贴板（确保无None）    pyperclip.copy(filename)    time.sleep(0.2)    # 2. 控件内粘贴（精准操作，无全局依赖）    edit_control.type_keys("^v", pause=0.01)    time.sleep(0.1)